const item = $input.first();
const headers = item.json.headers || {};

function header(name) {
  const wanted = name.toLowerCase();
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === wanted) {
      const value = headers[key];
      return Array.isArray(value) ? String(value[0] || '') : String(value || '');
    }
  }
  return '';
}

function rawFrom(binary) {
  if (!binary) return '';
  const entry = binary.data || binary.body;
  if (entry && entry.data) return Buffer.from(entry.data, 'base64').toString('utf8');
  return '';
}

let body = rawFrom(item.binary);
if (!body) {
  try {
    body = rawFrom($('AnyMoment webhook').first().binary);
  } catch (error) {
    body = '';
  }
}

const timestamp = header('x-anymoment-timestamp');
const signature = header('x-anymoment-signature').trim().toLowerCase();
const delivery = header('x-anymoment-delivery');
let prepareError = '';
if (!body) prepareError = 'Raw body is missing. Turn on the Webhook raw body option.';
else if (!timestamp || !signature) prepareError = 'Signature headers are missing.';
else if (!Number.isFinite(Number(timestamp))) prepareError = 'Timestamp is not a number.';
else if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) prepareError = 'Timestamp is outside the 300 second window.';
else if (!/^[0-9a-f]+$/.test(signature)) prepareError = 'Signature is not hex.';

let payload = null;
if (body && !prepareError) {
  try {
    payload = JSON.parse(body);
  } catch (error) {
    prepareError = 'Body is not JSON.';
  }
}

return [{
  json: {
    signedPayload: timestamp && body ? timestamp + '.' + body : '',
    signature,
    delivery,
    prepareError,
    payload,
    changeType: (payload && payload.change_type) || '',
    occurrenceTime: (payload && payload.occurrence_time) || null,
    event: (payload && payload.event) || null,
  },
}];

const item = $input.first().json;

function fail(reason) {
  return [{
    json: {
      valid: false,
      reason,
      delivery: item.delivery || '',
      payload: item.payload || null,
      changeType: item.changeType || '',
      occurrenceTime: item.occurrenceTime || null,
      event: item.event || null,
    },
  }];
}

if (item.prepareError) return fail(item.prepareError);
const left = String(item.expectedSignature || '').toLowerCase();
const right = String(item.signature || '').toLowerCase();
if (!left || left.length !== right.length) return fail('Signature does not match the raw body.');
let diff = 0;
for (let i = 0; i < left.length; i++) diff |= left.charCodeAt(i) ^ right.charCodeAt(i);
if (diff !== 0) return fail('Signature does not match the raw body.');

return [{
  json: {
    valid: true,
    reason: 'ok',
    delivery: item.delivery,
    payload: item.payload,
    changeType: item.changeType,
    occurrenceTime: item.occurrenceTime,
    event: item.event,
  },
}];
